from pathlib import Path
import re


def read(path: str) -> str:
    return Path(path).read_text()


def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)


def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    count = text.count(old)
    if count != 1:
        raise SystemExit(
            f"{path}: expected one exact match, found {count} for {old[:120]!r}"
        )
    write(path, text.replace(old, new, 1))


def replace_between(path: str, start: str, end: str, replacement: str) -> None:
    text = read(path)
    start_index = text.find(start)
    if start_index < 0:
        raise SystemExit(f"{path}: start marker not found: {start!r}")
    end_index = text.find(end, start_index)
    if end_index < 0:
        raise SystemExit(f"{path}: end marker not found: {end!r}")
    write(path, text[:start_index] + replacement + text[end_index:])


def insert_before_last(path: str, marker: str, content: str) -> None:
    text = read(path)
    index = text.rfind(marker)
    if index < 0:
        raise SystemExit(f"{path}: final marker not found")
    write(path, text[:index] + content + text[index:])

write('worker/blob-lifecycle/registration.ts', 'import { primaryD1 } from "../d1-primary";\nimport type { ManagedStorage } from "../managed-storage";\nimport type { Env } from "../types";\nimport type { ReusableManagedObject, ReusableR2Asset } from "./reuse";\n\ntype R2RegistrationCandidate = ReusableR2Asset & {\n  status: "pending" | "ready";\n};\n\ntype ManagedRegistrationCandidate = ReusableManagedObject & {\n  status: "failed" | "ready" | "orphaned";\n};\n\nexport class BlobRegistrationAuthorityUnavailableError extends Error {\n  constructor(detail: string) {\n    super(`Blob registration authority is unavailable: ${detail}`);\n    this.name = "BlobRegistrationAuthorityUnavailableError";\n  }\n}\n\nexport class ManagedRegistrationByteSizeMismatchError extends Error {\n  constructor() {\n    super("Managed provider reported a different byte size");\n    this.name = "ManagedRegistrationByteSizeMismatchError";\n  }\n}\n\nfunction authorityUnavailable(error: unknown) {\n  return new BlobRegistrationAuthorityUnavailableError(\n    error instanceof Error ? error.message : String(error),\n  );\n}\n\nasync function readR2RegistrationCandidate(\n  db: D1Database,\n  input: { id: string; objectKey: string; sha256: string },\n): Promise<R2RegistrationCandidate | null> {\n  return primaryD1(db).prepare(`\n    SELECT a.id, a.r2_key, a.original_name, a.mime_type,\n           a.byte_size, a.sha256, a.status\n    FROM assets a\n    WHERE a.id = ? AND a.r2_key = ? AND a.sha256 = ?\n      AND a.import_id IS NULL AND a.status IN (\'pending\', \'ready\')\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = \'r2\' AND biq.provider = \'r2\'\n          AND biq.object_key = a.r2_key\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = \'r2\' AND bg.provider = \'r2\'\n          AND bg.object_key = a.r2_key\n          AND bg.state IN (\'deleting\', \'deleted\')\n      )\n  `).bind(input.id, input.objectKey, input.sha256)\n    .first<R2RegistrationCandidate>();\n}\n\nasync function readManagedRegistrationCandidate(\n  db: D1Database,\n  input: {\n    id: string;\n    provider: string;\n    objectKey: string;\n    sha256: string;\n    byteSize: number;\n  },\n): Promise<ManagedRegistrationCandidate | null> {\n  return primaryD1(db).prepare(`\n    SELECT mso.id, mso.provider, mso.object_key, mso.original_name,\n           mso.mime_type, mso.byte_size, mso.sha256, mso.status\n    FROM managed_storage_objects mso\n    WHERE mso.id = ? AND mso.provider = ? AND mso.object_key = ?\n      AND mso.sha256 = ? AND mso.byte_size = ?\n      AND mso.status IN (\'failed\', \'ready\', \'orphaned\')\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = \'managed\'\n          AND biq.provider = mso.provider\n          AND biq.object_key = mso.object_key\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = \'managed\'\n          AND bg.provider = mso.provider\n          AND bg.object_key = mso.object_key\n          AND bg.state IN (\'deleting\', \'deleted\')\n      )\n  `).bind(\n    input.id,\n    input.provider,\n    input.objectKey,\n    input.sha256,\n    input.byteSize,\n  ).first<ManagedRegistrationCandidate>();\n}\n\nasync function findR2Winner(\n  findWinner: () => Promise<ReusableR2Asset | null>,\n) {\n  try {\n    return await findWinner();\n  } catch (error) {\n    throw authorityUnavailable(error);\n  }\n}\n\nasync function findManagedWinner(\n  findWinner: () => Promise<ReusableManagedObject | null>,\n) {\n  try {\n    return await findWinner();\n  } catch (error) {\n    throw authorityUnavailable(error);\n  }\n}\n\nexport interface RegisterR2AssetInput {\n  id: string;\n  objectKey: string;\n  originalName: string;\n  mimeType: string;\n  byteSize: number;\n  sha256: string;\n  actorEmail: string;\n  bytes: ArrayBuffer;\n  findWinner: () => Promise<ReusableR2Asset | null>;\n}\n\nexport interface R2AssetRegistration {\n  asset: ReusableR2Asset;\n  deduplicated: boolean;\n}\n\n/**\n * Register an R2 object without ever creating provider-only state.\n *\n * Metadata is durably staged before the provider PUT. A response loss before\n * that claim therefore creates no object, while a failure after PUT leaves a\n * pending row that ordinary GC can enumerate. Promotion is guarded against a\n * concurrent ready winner; the losing candidate remains a uniquely addressed,\n * tracked GC candidate and is never allowed to delete the winner\'s locator.\n */\nexport async function registerR2Asset(\n  env: Env,\n  input: RegisterR2AssetInput,\n): Promise<R2AssetRegistration> {\n  const initialWinner = await findR2Winner(input.findWinner);\n  if (initialWinner) {\n    return { asset: initialWinner, deduplicated: true };\n  }\n\n  const id = input.id;\n  const now = new Date().toISOString();\n  let candidate: R2RegistrationCandidate | null = null;\n  let insertError: unknown;\n\n  for (let attempt = 0; attempt < 2 && !candidate; attempt += 1) {\n    try {\n      await env.DB.prepare(`\n        INSERT INTO assets (\n          id, r2_key, original_name, mime_type, byte_size, status,\n          actor_email, created_at, sha256\n        ) VALUES (?, ?, ?, ?, ?, \'pending\', ?, ?, ?)\n      `).bind(\n        id,\n        input.objectKey,\n        input.originalName,\n        input.mimeType,\n        input.byteSize,\n        input.actorEmail,\n        now,\n        input.sha256,\n      ).run();\n      candidate = {\n        id,\n        r2_key: input.objectKey,\n        original_name: input.originalName,\n        mime_type: input.mimeType,\n        byte_size: input.byteSize,\n        sha256: input.sha256,\n        status: "pending",\n      };\n    } catch (error) {\n      insertError = error;\n      try {\n        candidate = await readR2RegistrationCandidate(env.DB, {\n          id,\n          objectKey: input.objectKey,\n          sha256: input.sha256,\n        });\n      } catch (verificationError) {\n        throw authorityUnavailable(verificationError);\n      }\n      if (candidate) break;\n\n      const winner = await findR2Winner(input.findWinner);\n      if (winner) return { asset: winner, deduplicated: true };\n      if (attempt === 1) throw error;\n    }\n  }\n  if (!candidate) {\n    throw insertError ?? new Error("R2 registration metadata could not be staged");\n  }\n  if (candidate.status === "ready") {\n    const { status: _status, ...asset } = candidate;\n    return { asset, deduplicated: false };\n  }\n\n  await env.ASSETS.put(input.objectKey, input.bytes, {\n    httpMetadata: { contentType: input.mimeType },\n  });\n\n  let promotionError: unknown;\n  for (let attempt = 0; attempt < 2; attempt += 1) {\n    let promoted = false;\n    try {\n      const result = await env.DB.prepare(`\n        UPDATE assets\n        SET status = \'ready\'\n        WHERE id = ? AND r2_key = ? AND sha256 = ?\n          AND import_id IS NULL AND status = \'pending\'\n          AND NOT EXISTS (\n            SELECT 1\n            FROM assets winner\n            WHERE winner.id <> assets.id\n              AND winner.sha256 = assets.sha256\n              AND winner.status = \'ready\'\n              AND NOT EXISTS (\n                SELECT 1 FROM blob_integrity_quarantine biq\n                WHERE biq.store_kind = \'r2\' AND biq.provider = \'r2\'\n                  AND biq.object_key = winner.r2_key\n              )\n              AND NOT EXISTS (\n                SELECT 1 FROM blob_gc_ledger bg\n                WHERE bg.store_kind = \'r2\' AND bg.provider = \'r2\'\n                  AND bg.object_key = winner.r2_key\n                  AND bg.state IN (\'deleting\', \'deleted\')\n              )\n          )\n          AND NOT EXISTS (\n            SELECT 1\n            FROM assets staged\n            JOIN imports owner ON owner.id = staged.import_id\n            WHERE staged.id <> assets.id\n              AND staged.sha256 = assets.sha256\n              AND staged.status IN (\'pending\', \'ready\')\n              AND owner.status = \'pending\'\n              AND NOT EXISTS (\n                SELECT 1 FROM blob_integrity_quarantine biq\n                WHERE biq.store_kind = \'r2\' AND biq.provider = \'r2\'\n                  AND biq.object_key = staged.r2_key\n              )\n              AND NOT EXISTS (\n                SELECT 1 FROM blob_gc_ledger bg\n                WHERE bg.store_kind = \'r2\' AND bg.provider = \'r2\'\n                  AND bg.object_key = staged.r2_key\n                  AND bg.state IN (\'deleting\', \'deleted\')\n              )\n          )\n      `).bind(id, input.objectKey, input.sha256).run();\n      promoted = Boolean(result.meta.changes);\n    } catch (error) {\n      promotionError = error;\n    }\n    if (promoted) {\n      return {\n        asset: {\n          id,\n          r2_key: input.objectKey,\n          original_name: input.originalName,\n          mime_type: input.mimeType,\n          byte_size: input.byteSize,\n          sha256: input.sha256,\n        },\n        deduplicated: false,\n      };\n    }\n\n    let exact: R2RegistrationCandidate | null;\n    try {\n      exact = await readR2RegistrationCandidate(env.DB, {\n        id,\n        objectKey: input.objectKey,\n        sha256: input.sha256,\n      });\n    } catch (verificationError) {\n      throw authorityUnavailable(verificationError);\n    }\n    if (exact?.status === "ready") {\n      const { status: _status, ...asset } = exact;\n      return { asset, deduplicated: false };\n    }\n\n    const winner = await findR2Winner(input.findWinner);\n    if (winner) {\n      try {\n        await env.DB.prepare(`\n          UPDATE assets\n          SET status = \'failed\', sha256 = NULL\n          WHERE id = ? AND r2_key = ? AND status = \'pending\'\n            AND NOT EXISTS (\n              SELECT 1 FROM blob_retention_edges bre\n              WHERE bre.store_kind = \'r2\' AND bre.provider = \'r2\'\n                AND bre.object_key = assets.r2_key\n            )\n        `).bind(id, input.objectKey).run();\n      } catch {\n        // The pending row still makes the uniquely addressed candidate\n        // discoverable to GC; winner resolution must not delete either locator.\n      }\n      return { asset: winner, deduplicated: true };\n    }\n\n    if (!exact) {\n      try {\n        await env.DB.prepare(`\n          INSERT INTO assets (\n            id, r2_key, original_name, mime_type, byte_size, status,\n            actor_email, created_at, sha256\n          ) VALUES (?, ?, ?, ?, ?, \'pending\', ?, ?, ?)\n        `).bind(\n          id,\n          input.objectKey,\n          input.originalName,\n          input.mimeType,\n          input.byteSize,\n          input.actorEmail,\n          now,\n          input.sha256,\n        ).run();\n      } catch (error) {\n        promotionError = error;\n      }\n    }\n    if (attempt === 1) {\n      throw promotionError\n        ?? new Error("R2 registration could not be promoted to ready");\n    }\n  }\n  throw promotionError ?? new Error("R2 registration could not be reconciled");\n}\n\nexport interface RegisterManagedObjectInput {\n  id: string;\n  objectKey: string;\n  originalName: string;\n  mimeType: string;\n  byteSize: number;\n  sha256: string;\n  actorEmail: string;\n  body: ReadableStream;\n  findWinner: () => Promise<ReusableManagedObject | null>;\n}\n\nexport interface ManagedObjectRegistration {\n  object: ReusableManagedObject;\n  deduplicated: boolean;\n}\n\n/**\n * Managed storage uses a failed metadata row as the non-public staging state.\n * The schema predates an explicit pending status, but failed rows are not\n * reusable and are now part of the ordinary tracked-GC surface.\n */\nexport async function registerManagedObject(\n  env: Env,\n  storage: ManagedStorage,\n  input: RegisterManagedObjectInput,\n): Promise<ManagedObjectRegistration> {\n  const initialWinner = await findManagedWinner(input.findWinner);\n  if (initialWinner) {\n    return { object: initialWinner, deduplicated: true };\n  }\n\n  const now = new Date().toISOString();\n  let candidate: ManagedRegistrationCandidate | null = null;\n  let insertError: unknown;\n  for (let attempt = 0; attempt < 2 && !candidate; attempt += 1) {\n    try {\n      await env.DB.prepare(`\n        INSERT INTO managed_storage_objects (\n          id, provider, object_key, original_name, mime_type, byte_size,\n          sha256, status, actor_email, created_at\n        ) VALUES (?, ?, ?, ?, ?, ?, ?, \'failed\', ?, ?)\n      `).bind(\n        input.id,\n        storage.provider,\n        input.objectKey,\n        input.originalName,\n        input.mimeType,\n        input.byteSize,\n        input.sha256,\n        input.actorEmail,\n        now,\n      ).run();\n      candidate = {\n        id: input.id,\n        provider: storage.provider,\n        object_key: input.objectKey,\n        original_name: input.originalName,\n        mime_type: input.mimeType,\n        byte_size: input.byteSize,\n        sha256: input.sha256,\n        status: "failed",\n      };\n    } catch (error) {\n      insertError = error;\n      try {\n        candidate = await readManagedRegistrationCandidate(env.DB, {\n          id: input.id,\n          provider: storage.provider,\n          objectKey: input.objectKey,\n          sha256: input.sha256,\n          byteSize: input.byteSize,\n        });\n      } catch (verificationError) {\n        throw authorityUnavailable(verificationError);\n      }\n      if (candidate) break;\n      const winner = await findManagedWinner(input.findWinner);\n      if (winner) return { object: winner, deduplicated: true };\n      if (attempt === 1) throw error;\n    }\n  }\n  if (!candidate) {\n    throw insertError ?? new Error("Managed registration metadata could not be staged");\n  }\n  if (candidate.status === "ready" || candidate.status === "orphaned") {\n    const { status: _status, ...object } = candidate;\n    return { object, deduplicated: false };\n  }\n\n  const stored = await storage.put({\n    key: input.objectKey,\n    body: input.body,\n    contentType: input.mimeType,\n    filename: input.originalName,\n    sha256: input.sha256,\n    byteSize: input.byteSize,\n  });\n  if (stored.byteSize !== input.byteSize) {\n    throw new ManagedRegistrationByteSizeMismatchError();\n  }\n\n  let promotionError: unknown;\n  for (let attempt = 0; attempt < 2; attempt += 1) {\n    let promoted = false;\n    try {\n      const result = await env.DB.prepare(`\n        UPDATE managed_storage_objects\n        SET status = \'ready\', orphaned_at = NULL\n        WHERE id = ? AND provider = ? AND object_key = ?\n          AND sha256 = ? AND byte_size = ? AND status = \'failed\'\n          AND NOT EXISTS (\n            SELECT 1\n            FROM managed_storage_objects winner\n            WHERE winner.id <> managed_storage_objects.id\n              AND winner.provider = managed_storage_objects.provider\n              AND winner.sha256 = managed_storage_objects.sha256\n              AND winner.byte_size = managed_storage_objects.byte_size\n              AND winner.status IN (\'ready\', \'orphaned\')\n              AND NOT EXISTS (\n                SELECT 1 FROM blob_integrity_quarantine biq\n                WHERE biq.store_kind = \'managed\'\n                  AND biq.provider = winner.provider\n                  AND biq.object_key = winner.object_key\n              )\n              AND NOT EXISTS (\n                SELECT 1 FROM blob_gc_ledger bg\n                WHERE bg.store_kind = \'managed\'\n                  AND bg.provider = winner.provider\n                  AND bg.object_key = winner.object_key\n                  AND bg.state IN (\'deleting\', \'deleted\')\n              )\n          )\n      `).bind(\n        input.id,\n        storage.provider,\n        input.objectKey,\n        input.sha256,\n        input.byteSize,\n      ).run();\n      promoted = Boolean(result.meta.changes);\n    } catch (error) {\n      promotionError = error;\n    }\n    if (promoted) {\n      return {\n        object: {\n          id: input.id,\n          provider: storage.provider,\n          object_key: input.objectKey,\n          original_name: input.originalName,\n          mime_type: input.mimeType,\n          byte_size: input.byteSize,\n          sha256: input.sha256,\n        },\n        deduplicated: false,\n      };\n    }\n\n    let exact: ManagedRegistrationCandidate | null;\n    try {\n      exact = await readManagedRegistrationCandidate(env.DB, {\n        id: input.id,\n        provider: storage.provider,\n        objectKey: input.objectKey,\n        sha256: input.sha256,\n        byteSize: input.byteSize,\n      });\n    } catch (verificationError) {\n      throw authorityUnavailable(verificationError);\n    }\n    if (exact?.status === "ready" || exact?.status === "orphaned") {\n      const { status: _status, ...object } = exact;\n      return { object, deduplicated: false };\n    }\n\n    const winner = await findManagedWinner(input.findWinner);\n    if (winner) {\n      return { object: winner, deduplicated: true };\n    }\n    if (attempt === 1) {\n      throw promotionError\n        ?? new Error("Managed registration could not be promoted to ready");\n    }\n  }\n  throw promotionError ?? new Error("Managed registration could not be reconciled");\n}\n')
write('worker/fabublox-recovery-assets.ts', 'import { sha256Hex } from "../shared/content-addressing";\nimport {\n  BlobReuseProviderUnavailableError,\n  findReusableR2Asset,\n  type ReusableR2Asset,\n} from "./blob-lifecycle/reuse";\nimport { getBlob, statBlob } from "./blob-lifecycle/storage";\nimport type { BlobLocator } from "./blob-lifecycle/types";\nimport type { Env } from "./types";\n\ninterface RecoveryAssetRow {\n  id: string;\n  r2_key: string;\n  byte_size: number;\n  sha256: string | null;\n  status: "pending" | "ready" | "failed";\n  quarantine_reason: "missing" | "size_mismatch" | null;\n  quarantine_expected_byte_size: number | null;\n  quarantine_observed_byte_size: number | null;\n  gc_state: "orphaned" | "deleting" | "deleted" | null;\n}\n\nexport interface FabubloxRecoveryAssetInspection {\n  id: string;\n  objectKey: string;\n  available: boolean;\n  sha256: string | null;\n  byteSize: number;\n  quarantineReason: "missing" | "size_mismatch" | null;\n  expectedByteSize: number;\n  observedByteSize: number | null;\n  canonicalAssetId: string | null;\n  canonicalObjectKey: string | null;\n}\n\nexport class FabubloxRecoveryProviderUnavailableError extends Error {\n  constructor(objectKey: string, detail: string) {\n    super(`Could not verify FabuBlox recovery asset ${objectKey}: ${detail}`);\n    this.name = "FabubloxRecoveryProviderUnavailableError";\n  }\n}\n\nfunction locator(row: RecoveryAssetRow): BlobLocator {\n  return {\n    storeKind: "r2",\n    provider: "r2",\n    objectKey: row.r2_key,\n    blobRecordId: row.id,\n  };\n}\n\nfunction unavailable(\n  row: RecoveryAssetRow,\n  reason: "missing" | "size_mismatch" | null,\n  observedByteSize: number | null,\n): FabubloxRecoveryAssetInspection {\n  return {\n    id: row.id,\n    objectKey: row.r2_key,\n    available: false,\n    sha256: null,\n    byteSize: Number(row.byte_size),\n    quarantineReason: reason,\n    expectedByteSize: Number(row.byte_size),\n    observedByteSize,\n    canonicalAssetId: null,\n    canonicalObjectKey: null,\n  };\n}\n\nasync function canonicalWinner(\n  env: Env,\n  objectKey: string,\n  sha256: string,\n  byteSize: number,\n): Promise<ReusableR2Asset | null> {\n  try {\n    const winner = await findReusableR2Asset(env, sha256);\n    if (!winner) return null;\n    if (Number(winner.byte_size) !== byteSize) {\n      throw new Error(\n        `Canonical asset ${winner.id} has byte-size metadata inconsistent with recovered SHA-256`,\n      );\n    }\n    return winner;\n  } catch (error) {\n    if (error instanceof BlobReuseProviderUnavailableError\n      && error.message.includes("matching bytes are still owned by a pending FabuBlox import")) {\n      // A pending import is a private successor, not a public canonical winner.\n      // The recovery ownership graph will handle that case after the claim.\n      return null;\n    }\n    if (error instanceof BlobReuseProviderUnavailableError) {\n      throw new FabubloxRecoveryProviderUnavailableError(objectKey, error.message);\n    }\n    throw error;\n  }\n}\n\nfunction availableInspection(\n  row: RecoveryAssetRow,\n  sha256: string,\n  byteSize: number,\n  canonical: ReusableR2Asset | null,\n): FabubloxRecoveryAssetInspection {\n  return {\n    id: row.id,\n    objectKey: row.r2_key,\n    available: true,\n    sha256,\n    byteSize,\n    quarantineReason: null,\n    expectedByteSize: Number(row.byte_size),\n    observedByteSize: byteSize,\n    canonicalAssetId: canonical?.id ?? null,\n    canonicalObjectKey: canonical?.r2_key ?? null,\n  };\n}\n\nexport async function inspectFabubloxRecoveryAssets(\n  env: Env,\n  db: D1Database,\n  importId: string,\n): Promise<FabubloxRecoveryAssetInspection[]> {\n  const rows = await db.prepare(`\n    SELECT a.id, a.r2_key, a.byte_size, a.sha256, a.status,\n           biq.reason AS quarantine_reason,\n           biq.expected_byte_size AS quarantine_expected_byte_size,\n           biq.observed_byte_size AS quarantine_observed_byte_size,\n           bg.state AS gc_state\n    FROM assets a\n    LEFT JOIN blob_integrity_quarantine biq\n      ON biq.store_kind = \'r2\' AND biq.provider = \'r2\'\n     AND biq.object_key = a.r2_key\n    LEFT JOIN blob_gc_ledger bg\n      ON bg.store_kind = \'r2\' AND bg.provider = \'r2\'\n     AND bg.object_key = a.r2_key\n    WHERE a.import_id = ? AND a.status IN (\'pending\', \'ready\', \'failed\')\n    ORDER BY a.created_at, a.id\n  `).bind(importId).all<RecoveryAssetRow>();\n\n  const inspections: FabubloxRecoveryAssetInspection[] = [];\n  for (const row of rows.results) {\n    if (row.quarantine_reason) {\n      inspections.push({\n        id: row.id,\n        objectKey: row.r2_key,\n        available: false,\n        sha256: null,\n        byteSize: Number(row.byte_size),\n        quarantineReason: row.quarantine_reason,\n        expectedByteSize: Number(\n          row.quarantine_expected_byte_size ?? row.byte_size,\n        ),\n        observedByteSize: row.quarantine_observed_byte_size === null\n          ? null\n          : Number(row.quarantine_observed_byte_size),\n        canonicalAssetId: null,\n        canonicalObjectKey: null,\n      });\n      continue;\n    }\n    if (row.gc_state === "deleting" || row.gc_state === "deleted") {\n      inspections.push(unavailable(row, null, null));\n      continue;\n    }\n\n    if (row.sha256 === null) {\n      const read = await getBlob(env, locator(row));\n      if (read.outcome === "provider_unavailable") {\n        throw new FabubloxRecoveryProviderUnavailableError(row.r2_key, read.message);\n      }\n      if (read.outcome === "missing") {\n        inspections.push(unavailable(row, "missing", null));\n        continue;\n      }\n      const bytes = await new Response(read.body).arrayBuffer();\n      const sha256 = await sha256Hex(bytes);\n      const canonical = await canonicalWinner(\n        env,\n        row.r2_key,\n        sha256,\n        bytes.byteLength,\n      );\n      inspections.push(availableInspection(\n        row,\n        sha256,\n        bytes.byteLength,\n        canonical,\n      ));\n      continue;\n    }\n\n    const stat = await statBlob(env, locator(row));\n    if (stat.outcome === "provider_unavailable") {\n      throw new FabubloxRecoveryProviderUnavailableError(row.r2_key, stat.message);\n    }\n    if (stat.outcome === "missing") {\n      inspections.push(unavailable(row, "missing", null));\n      continue;\n    }\n    if (stat.byteSize === null) {\n      throw new FabubloxRecoveryProviderUnavailableError(\n        row.r2_key,\n        "R2 did not return a stable byte size",\n      );\n    }\n    if (stat.byteSize !== Number(row.byte_size)) {\n      inspections.push(unavailable(row, "size_mismatch", stat.byteSize));\n      continue;\n    }\n    const canonical = await canonicalWinner(\n      env,\n      row.r2_key,\n      row.sha256,\n      Number(row.byte_size),\n    );\n    inspections.push(availableInspection(\n      row,\n      row.sha256,\n      Number(row.byte_size),\n      canonical,\n    ));\n  }\n  return inspections;\n}\n')
write('migrations/0028_blob_registration_and_recovery_reconciliation.sql', "PRAGMA foreign_keys = ON;\n\n-- Registration now stages metadata before provider writes. Promotion from the\n-- non-public staging state must obey the same live-SHA boundary that INSERT\n-- already enforces, including the private reservation held by a pending import.\n\nCREATE TRIGGER assets_reject_live_sha_duplicate_update\nBEFORE UPDATE OF status, sha256 ON assets\nWHEN NEW.status = 'ready' AND NEW.sha256 IS NOT NULL\n  AND EXISTS (\n    SELECT 1\n    FROM assets a\n    WHERE a.id <> OLD.id\n      AND a.sha256 = NEW.sha256\n      AND a.status = 'ready'\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = 'r2' AND bg.provider = 'r2'\n          AND bg.object_key = a.r2_key\n          AND bg.state IN ('deleting', 'deleted')\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = 'r2' AND biq.provider = 'r2'\n          AND biq.object_key = a.r2_key\n      )\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'UNIQUE live asset sha256 already registered');\nEND;\n\nCREATE TRIGGER assets_reject_pending_import_sha_publication_insert\nBEFORE INSERT ON assets\nWHEN NEW.import_id IS NULL\n  AND NEW.status = 'ready'\n  AND NEW.sha256 IS NOT NULL\n  AND EXISTS (\n    SELECT 1\n    FROM assets staged\n    JOIN imports owner ON owner.id = staged.import_id\n    WHERE staged.sha256 = NEW.sha256\n      AND staged.status IN ('pending', 'ready')\n      AND owner.status = 'pending'\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = 'r2' AND bg.provider = 'r2'\n          AND bg.object_key = staged.r2_key\n          AND bg.state IN ('deleting', 'deleted')\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = 'r2' AND biq.provider = 'r2'\n          AND biq.object_key = staged.r2_key\n      )\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'matching asset is owned by a pending import');\nEND;\n\nCREATE TRIGGER assets_reject_pending_import_sha_publication_update\nBEFORE UPDATE OF status, sha256, import_id ON assets\nWHEN NEW.import_id IS NULL\n  AND NEW.status = 'ready'\n  AND NEW.sha256 IS NOT NULL\n  AND EXISTS (\n    SELECT 1\n    FROM assets staged\n    JOIN imports owner ON owner.id = staged.import_id\n    WHERE staged.id <> OLD.id\n      AND staged.sha256 = NEW.sha256\n      AND staged.status IN ('pending', 'ready')\n      AND owner.status = 'pending'\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = 'r2' AND bg.provider = 'r2'\n          AND bg.object_key = staged.r2_key\n          AND bg.state IN ('deleting', 'deleted')\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = 'r2' AND biq.provider = 'r2'\n          AND biq.object_key = staged.r2_key\n      )\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'matching asset is owned by a pending import');\nEND;\n\n-- Recovery may discover that a legacy failed locator contains bytes already\n-- represented by a healthy canonical asset. Stable occurrence identities must\n-- then be rebound without reopening ordinary mutation of unpublished templates\n-- or immutable Project attachment metadata. These exceptions are deliberately\n-- limited to an exact same-SHA, same-size winner after a durable recovery claim.\n\nDROP TRIGGER template_versions_guard_unpublished_update;\n\nCREATE TRIGGER template_versions_guard_unpublished_update\nBEFORE UPDATE ON template_versions\nWHEN EXISTS (\n  SELECT 1 FROM imports i\n  WHERE i.template_version_id = OLD.id AND i.status = 'pending'\n)\nAND NOT (\n  OLD.id IS NEW.id\n  AND OLD.recipe_family_id IS NEW.recipe_family_id\n  AND OLD.name IS NEW.name\n  AND OLD.template_type IS NEW.template_type\n  AND OLD.version IS NEW.version\n  AND OLD.manifest_hash IS NEW.manifest_hash\n  AND OLD.initial_state_hash IS NEW.initial_state_hash\n  AND OLD.source_filename IS NEW.source_filename\n  AND OLD.source_asset_key IS NOT NEW.source_asset_key\n  AND OLD.content_json IS NEW.content_json\n  AND OLD.created_by IS NEW.created_by\n  AND OLD.created_at IS NEW.created_at\n  AND OLD.locked_at IS NEW.locked_at\n  AND OLD.locked_by IS NEW.locked_by\n  AND OLD.archived_at IS NEW.archived_at\n  AND OLD.archived_by IS NEW.archived_by\n  AND OLD.template_kind IS NEW.template_kind\n  AND OLD.metrology_notes IS NEW.metrology_notes\n  AND OLD.deleted_at IS NEW.deleted_at\n  AND OLD.deleted_by IS NEW.deleted_by\n  AND EXISTS (\n    SELECT 1\n    FROM assets legacy\n    JOIN imports failed_owner ON failed_owner.id = legacy.import_id\n    JOIN assets canonical ON canonical.r2_key = NEW.source_asset_key\n    LEFT JOIN imports canonical_owner ON canonical_owner.id = canonical.import_id\n    WHERE legacy.r2_key = OLD.source_asset_key\n      AND failed_owner.status = 'failed'\n      AND failed_owner.recovery_operation_id IS NOT NULL\n      AND legacy.sha256 IS NOT NULL\n      AND canonical.sha256 = legacy.sha256\n      AND canonical.byte_size = legacy.byte_size\n      AND canonical.status = 'ready'\n      AND (\n        canonical.import_id IS NULL\n        OR canonical_owner.status = 'ready'\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = 'r2' AND biq.provider = 'r2'\n          AND biq.object_key = canonical.r2_key\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = 'r2' AND bg.provider = 'r2'\n          AND bg.object_key = canonical.r2_key\n          AND bg.state IN ('deleting', 'deleted')\n      )\n  )\n)\nBEGIN\n  SELECT RAISE(ABORT, 'template version is not published');\nEND;\n\nDROP TRIGGER metrology_template_references_guard_publication_update;\n\nCREATE TRIGGER metrology_template_references_guard_publication_update\nBEFORE UPDATE OF template_version_id, asset_id ON metrology_template_references\nBEGIN\n  SELECT RAISE(ABORT, 'template version is not published')\n  WHERE EXISTS (\n    SELECT 1 FROM imports i\n    WHERE i.template_version_id = NEW.template_version_id AND i.status <> 'ready'\n  )\n  AND NOT (\n    OLD.id IS NEW.id\n    AND OLD.template_version_id IS NEW.template_version_id\n    AND OLD.asset_id IS NOT NEW.asset_id\n    AND OLD.display_name IS NEW.display_name\n    AND OLD.position IS NEW.position\n    AND OLD.actor_email IS NEW.actor_email\n    AND OLD.created_at IS NEW.created_at\n    AND OLD.deleted_at IS NEW.deleted_at\n    AND OLD.deleted_by IS NEW.deleted_by\n    AND EXISTS (\n      SELECT 1\n      FROM assets legacy\n      JOIN imports failed_owner ON failed_owner.id = legacy.import_id\n      JOIN assets canonical ON canonical.id = NEW.asset_id\n      LEFT JOIN imports canonical_owner ON canonical_owner.id = canonical.import_id\n      WHERE legacy.id = OLD.asset_id\n        AND failed_owner.status = 'failed'\n        AND failed_owner.recovery_operation_id IS NOT NULL\n        AND legacy.sha256 IS NOT NULL\n        AND canonical.sha256 = legacy.sha256\n        AND canonical.byte_size = legacy.byte_size\n        AND canonical.status = 'ready'\n        AND (\n          canonical.import_id IS NULL\n          OR canonical_owner.status = 'ready'\n        )\n        AND NOT EXISTS (\n          SELECT 1 FROM blob_integrity_quarantine biq\n          WHERE biq.store_kind = 'r2' AND biq.provider = 'r2'\n            AND biq.object_key = canonical.r2_key\n        )\n        AND NOT EXISTS (\n          SELECT 1 FROM blob_gc_ledger bg\n          WHERE bg.store_kind = 'r2' AND bg.provider = 'r2'\n            AND bg.object_key = canonical.r2_key\n            AND bg.state IN ('deleting', 'deleted')\n        )\n    )\n  );\n\n  SELECT RAISE(ABORT, 'asset owning import is not ready') WHERE NOT EXISTS (\n    SELECT 1\n    FROM assets a\n    LEFT JOIN imports i ON i.id = a.import_id\n    WHERE a.id = NEW.asset_id AND a.status = 'ready'\n      AND (a.import_id IS NULL OR i.status = 'ready')\n  );\nEND;\n\nDROP TRIGGER project_content_attachments_reject_update;\n\nCREATE TRIGGER project_content_attachments_reject_update\nBEFORE UPDATE ON project_content_attachments\nWHEN NOT (\n  OLD.project_content_id IS NEW.project_content_id\n  AND OLD.asset_id IS NOT NEW.asset_id\n  AND OLD.asset_id IS NOT NULL\n  AND NEW.asset_id IS NOT NULL\n  AND OLD.storage_object_id IS NULL\n  AND NEW.storage_object_id IS NULL\n  AND OLD.original_name IS NEW.original_name\n  AND OLD.mime_type IS NEW.mime_type\n  AND OLD.byte_size IS NEW.byte_size\n  AND OLD.created_by IS NEW.created_by\n  AND OLD.created_at IS NEW.created_at\n  AND OLD.creation_operation_id IS NEW.creation_operation_id\n  AND EXISTS (\n    SELECT 1\n    FROM assets legacy\n    JOIN imports failed_owner ON failed_owner.id = legacy.import_id\n    JOIN assets canonical ON canonical.id = NEW.asset_id\n    LEFT JOIN imports canonical_owner ON canonical_owner.id = canonical.import_id\n    WHERE legacy.id = OLD.asset_id\n      AND failed_owner.status = 'failed'\n      AND failed_owner.recovery_operation_id IS NOT NULL\n      AND legacy.sha256 IS NOT NULL\n      AND canonical.sha256 = legacy.sha256\n      AND canonical.byte_size = legacy.byte_size\n      AND canonical.status = 'ready'\n      AND (\n        canonical.import_id IS NULL\n        OR canonical_owner.status = 'ready'\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_integrity_quarantine biq\n        WHERE biq.store_kind = 'r2' AND biq.provider = 'r2'\n          AND biq.object_key = canonical.r2_key\n      )\n      AND NOT EXISTS (\n        SELECT 1 FROM blob_gc_ledger bg\n        WHERE bg.store_kind = 'r2' AND bg.provider = 'r2'\n          AND bg.object_key = canonical.r2_key\n          AND bg.state IN ('deleting', 'deleted')\n      )\n  )\n)\nBEGIN\n  SELECT RAISE(ABORT, 'project attachment intrinsic metadata is immutable');\nEND;\n")
write('worker/blob-registration-concurrency.test.ts', 'import { readFileSync, readdirSync } from "node:fs";\nimport { DatabaseSync } from "node:sqlite";\nimport { afterEach, describe, expect, it, vi } from "vitest";\nimport { sha256Hex } from "../shared/content-addressing";\nimport worker from "./index";\nimport { SqliteD1Database } from "./reference-test-support";\nimport type { Env } from "./types";\n\nconst executionContext = {\n  waitUntil: () => undefined,\n  passThroughOnException: () => undefined,\n  props: {},\n} as unknown as ExecutionContext;\n\nfunction deferred() {\n  let resolve!: () => void;\n  const promise = new Promise<void>((done) => {\n    resolve = done;\n  });\n  return { promise, resolve };\n}\n\nfunction databaseWithUpload(\n  kind: "comment_image" | "attachment",\n  byteSize: number,\n) {\n  const database = new DatabaseSync(":memory:");\n  const migrationDirectory = new URL("../migrations/", import.meta.url);\n  for (const filename of readdirSync(migrationDirectory)\n    .filter((name) => name.endsWith(".sql"))\n    .sort()) {\n    database.exec(readFileSync(new URL(filename, migrationDirectory), "utf8"));\n  }\n  database.exec(`\n    INSERT INTO samples (id, code, title, status, created_at, updated_at)\n    VALUES (\n      \'sample-upload\', \'UPLOAD-1\', \'Upload sample\', \'stored\',\n      \'2026-08-15T10:00:00.000Z\', \'2026-08-15T10:00:00.000Z\'\n    );\n\n    INSERT INTO comment_submissions (\n      id, context_kind, sample_id, scope, body, status, actor_email,\n      created_at, updated_at, retry_until\n    ) VALUES (\n      \'submission-upload\', \'sample\', \'sample-upload\', NULL, \'\', \'uploading\',\n      \'local-development\', \'2026-08-15T10:01:00.000Z\',\n      \'2026-08-15T10:01:00.000Z\', \'2026-08-16T10:01:00.000Z\'\n    );\n\n    INSERT INTO comment_submission_items (\n      id, submission_id, kind, status, position, filename, mime_type,\n      byte_size, created_at, updated_at\n    ) VALUES (\n      \'item-upload\', \'submission-upload\', \'${kind}\', \'pending\', 0,\n      \'${kind === "comment_image" ? "image.png" : "result.dat"}\',\n      \'${kind === "comment_image" ? "image/png" : "application/octet-stream"}\',\n      ${byteSize}, \'2026-08-15T10:01:00.000Z\', \'2026-08-15T10:01:00.000Z\'\n    );\n  `);\n  return database;\n}\n\nfunction bytesBuffer(bytes: Uint8Array) {\n  return bytes.buffer.slice(\n    bytes.byteOffset,\n    bytes.byteOffset + bytes.byteLength,\n  ) as ArrayBuffer;\n}\n\nfunction r2Object(bytes: Uint8Array, contentType: string) {\n  return {\n    body: new ReadableStream<Uint8Array>({\n      start(controller) {\n        controller.enqueue(bytes);\n        controller.close();\n      },\n    }),\n    size: bytes.byteLength,\n    httpEtag: \'"concurrency-test"\',\n    writeHttpMetadata(headers: Headers) {\n      headers.set("content-type", contentType);\n    },\n  };\n}\n\nfunction uploadRequest(bytes: Uint8Array, kind: "comment_image" | "attachment", sha256?: string) {\n  const headers: Record<string, string> = {\n    "content-type": kind === "comment_image"\n      ? "image/png"\n      : "application/octet-stream",\n    "x-upload-size": String(bytes.byteLength),\n  };\n  if (sha256) headers["x-content-sha256"] = sha256;\n  return new Request(\n    "https://app.test/api/comment-submissions/submission-upload/items/item-upload/content",\n    {\n      method: "PUT",\n      headers,\n      body: bytes,\n    },\n  );\n}\n\nasync function runConcurrentR2Uploads(\n  firstBytes: Uint8Array,\n  secondBytes: Uint8Array,\n) {\n  const database = databaseWithUpload("comment_image", firstBytes.byteLength);\n  const stored = new Map<string, Uint8Array>();\n  const deleted: string[] = [];\n  const firstPutEntered = deferred();\n  const releaseFirstPut = deferred();\n  let putCount = 0;\n  const env = {\n    AUTH_MODE: "disabled",\n    DB: new SqliteD1Database(database) as unknown as D1Database,\n    ASSETS: {\n      put: vi.fn(async (key: string, value: unknown) => {\n        if (!(value instanceof ArrayBuffer)) {\n          throw new Error("Expected an ArrayBuffer");\n        }\n        putCount += 1;\n        if (putCount === 1) {\n          firstPutEntered.resolve();\n          await releaseFirstPut.promise;\n        }\n        stored.set(key, new Uint8Array(value.slice(0)));\n      }),\n      delete: vi.fn(async (key: string) => {\n        deleted.push(key);\n        stored.delete(key);\n      }),\n      head: vi.fn(async (key: string) => {\n        const value = stored.get(key);\n        return value ? r2Object(value, "image/png") : null;\n      }),\n      get: vi.fn(async (key: string) => {\n        const value = stored.get(key);\n        return value ? r2Object(value, "image/png") : null;\n      }),\n      list: vi.fn(async () => ({ objects: [], truncated: false })),\n    } as unknown as R2Bucket,\n  } satisfies Env;\n\n  const first = worker.fetch(\n    uploadRequest(firstBytes, "comment_image"),\n    env,\n    executionContext,\n  );\n  await firstPutEntered.promise;\n  const second = await worker.fetch(\n    uploadRequest(secondBytes, "comment_image"),\n    env,\n    executionContext,\n  );\n  releaseFirstPut.resolve();\n  const firstResponse = await first;\n  return { database, stored, deleted, firstResponse, second };\n}\n\nasync function runConcurrentManagedUploads(\n  firstBytes: Uint8Array,\n  secondBytes: Uint8Array,\n) {\n  const database = databaseWithUpload("attachment", firstBytes.byteLength);\n  const firstSha = await sha256Hex(bytesBuffer(firstBytes));\n  const secondSha = await sha256Hex(bytesBuffer(secondBytes));\n  const stored = new Map<string, Uint8Array>();\n  const deletedUrls: string[] = [];\n  const firstPutEntered = deferred();\n  const releaseFirstPut = deferred();\n  let putCount = 0;\n  const fetchMock = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {\n    const url = String(input);\n    const method = init?.method || "GET";\n    if (method === "MKCOL") return new Response(null, { status: 201 });\n    if (method === "PUT") {\n      putCount += 1;\n      if (putCount === 1) {\n        firstPutEntered.resolve();\n        await releaseFirstPut.promise;\n      }\n      const body = await new Response(init?.body as BodyInit).arrayBuffer();\n      stored.set(url, new Uint8Array(body));\n      return new Response(null, { status: 201 });\n    }\n    if (method === "HEAD") {\n      const value = stored.get(url);\n      if (!value) return new Response(null, { status: 404 });\n      return new Response(null, {\n        status: 200,\n        headers: {\n          "content-length": String(value.byteLength),\n          "content-type": "application/octet-stream",\n          etag: \'"managed-concurrency-test"\',\n        },\n      });\n    }\n    if (method === "GET") {\n      const value = stored.get(url);\n      return value\n        ? new Response(value, {\n            status: 200,\n            headers: {\n              "content-type": "application/octet-stream",\n              etag: \'"managed-concurrency-test"\',\n            },\n          })\n        : new Response(null, { status: 404 });\n    }\n    if (method === "DELETE") {\n      deletedUrls.push(url);\n      stored.delete(url);\n      return new Response(null, { status: 204 });\n    }\n    throw new Error(`Unexpected SWITCHdrive method ${method}`);\n  });\n  vi.stubGlobal("fetch", fetchMock);\n\n  const env = {\n    AUTH_MODE: "disabled",\n    DB: new SqliteD1Database(database) as unknown as D1Database,\n    ASSETS: {} as R2Bucket,\n    MANAGED_STORAGE_PROVIDER: "switchdrive",\n    SWITCHDRIVE_WEBDAV_URL:\n      "https://drive.switch.ch/remote.php/dav/files/test-user/",\n    SWITCHDRIVE_USERNAME: "test-user",\n    SWITCHDRIVE_APP_PASSWORD: "test-password",\n  } satisfies Env;\n\n  const first = worker.fetch(\n    uploadRequest(firstBytes, "attachment", firstSha),\n    env,\n    executionContext,\n  );\n  await firstPutEntered.promise;\n  const second = await worker.fetch(\n    uploadRequest(secondBytes, "attachment", secondSha),\n    env,\n    executionContext,\n  );\n  releaseFirstPut.resolve();\n  const firstResponse = await first;\n  return {\n    database,\n    stored,\n    deletedUrls,\n    firstResponse,\n    second,\n    firstSha,\n    secondSha,\n  };\n}\n\nafterEach(() => {\n  vi.unstubAllGlobals();\n});\n\ndescribe("concurrent Comment provider registration", () => {\n  it("keeps the canonical R2 bytes when same-SHA uploads race for one item", async () => {\n    const bytes = Uint8Array.from([137, 80, 78, 71, 1, 2, 3, 4]);\n    const result = await runConcurrentR2Uploads(bytes, bytes);\n    expect(result.firstResponse.status).toBe(200);\n    expect(result.second.status).toBe(200);\n    expect(result.deleted).toEqual([]);\n\n    const rows = result.database.prepare(`\n      SELECT id, r2_key, status, sha256\n      FROM assets\n      ORDER BY id\n    `).all() as Array<{\n      id: string;\n      r2_key: string;\n      status: string;\n      sha256: string | null;\n    }>;\n    expect(rows).toHaveLength(2);\n    expect(new Set(rows.map((row) => row.r2_key)).size).toBe(2);\n    expect(rows.map((row) => row.status).sort()).toEqual(["failed", "ready"]);\n    expect(result.stored.size).toBe(2);\n\n    const winner = result.database.prepare(`\n      SELECT a.r2_key, a.status\n      FROM comment_submission_items csi\n      JOIN assets a ON a.id = csi.asset_id\n      WHERE csi.id = \'item-upload\'\n    `).get() as { r2_key: string; status: string };\n    expect(winner.status).toBe("ready");\n    expect(result.stored.get(winner.r2_key)).toEqual(bytes);\n    result.database.close();\n  });\n\n  it("uses distinct R2 locators for different-SHA same-size uploads racing for one item", async () => {\n    const firstBytes = Uint8Array.from([137, 80, 78, 71, 11, 12, 13, 14]);\n    const secondBytes = Uint8Array.from([137, 80, 78, 71, 21, 22, 23, 24]);\n    const result = await runConcurrentR2Uploads(firstBytes, secondBytes);\n    expect(result.firstResponse.status).toBe(200);\n    expect(result.second.status).toBe(200);\n    expect(result.deleted).toEqual([]);\n\n    const rows = result.database.prepare(`\n      SELECT r2_key, status, sha256\n      FROM assets\n      ORDER BY id\n    `).all() as Array<{\n      r2_key: string;\n      status: string;\n      sha256: string;\n    }>;\n    expect(rows).toHaveLength(2);\n    expect(rows.every((row) => row.status === "ready")).toBe(true);\n    expect(new Set(rows.map((row) => row.r2_key)).size).toBe(2);\n    expect(new Set(rows.map((row) => row.sha256)).size).toBe(2);\n    expect([...result.stored.values()]).toEqual(\n      expect.arrayContaining([firstBytes, secondBytes]),\n    );\n\n    const winner = result.database.prepare(`\n      SELECT a.r2_key\n      FROM comment_submission_items csi\n      JOIN assets a ON a.id = csi.asset_id\n      WHERE csi.id = \'item-upload\'\n    `).get() as { r2_key: string };\n    expect(result.stored.has(winner.r2_key)).toBe(true);\n    result.database.close();\n  });\n\n  it("keeps the canonical managed bytes when same-SHA uploads race for one item", async () => {\n    const bytes = Uint8Array.from([41, 42, 43, 44, 45, 46]);\n    const result = await runConcurrentManagedUploads(bytes, bytes);\n    expect(result.firstResponse.status).toBe(200);\n    expect(result.second.status).toBe(200);\n    expect(result.deletedUrls).toEqual([]);\n\n    const rows = result.database.prepare(`\n      SELECT id, object_key, status, sha256\n      FROM managed_storage_objects\n      ORDER BY id\n    `).all() as Array<{\n      id: string;\n      object_key: string;\n      status: string;\n      sha256: string;\n    }>;\n    expect(rows).toHaveLength(2);\n    expect(new Set(rows.map((row) => row.object_key)).size).toBe(2);\n    expect(rows.map((row) => row.status).sort()).toEqual(["failed", "ready"]);\n    expect(result.stored.size).toBe(2);\n\n    const winner = result.database.prepare(`\n      SELECT mso.object_key, mso.status\n      FROM comment_submission_items csi\n      JOIN managed_storage_objects mso ON mso.id = csi.storage_object_id\n      WHERE csi.id = \'item-upload\'\n    `).get() as { object_key: string; status: string };\n    expect(winner.status).toBe("ready");\n    const winnerUrl = [\n      "https://drive.switch.ch/remote.php/dav/files/test-user",\n      "sample-fabrication-workflow",\n      ...winner.object_key.split("/").map(encodeURIComponent),\n    ].join("/");\n    expect(result.stored.get(winnerUrl)).toEqual(bytes);\n    result.database.close();\n  });\n\n  it("uses distinct managed locators for different-SHA same-size uploads racing for one item", async () => {\n    const firstBytes = Uint8Array.from([51, 52, 53, 54, 55, 56]);\n    const secondBytes = Uint8Array.from([61, 62, 63, 64, 65, 66]);\n    const result = await runConcurrentManagedUploads(firstBytes, secondBytes);\n    expect(result.firstResponse.status).toBe(200);\n    expect(result.second.status).toBe(200);\n    expect(result.deletedUrls).toEqual([]);\n\n    const rows = result.database.prepare(`\n      SELECT object_key, status, sha256\n      FROM managed_storage_objects\n      ORDER BY id\n    `).all() as Array<{\n      object_key: string;\n      status: string;\n      sha256: string;\n    }>;\n    expect(rows).toHaveLength(2);\n    expect(rows.every((row) => row.status === "ready")).toBe(true);\n    expect(new Set(rows.map((row) => row.object_key)).size).toBe(2);\n    expect(new Set(rows.map((row) => row.sha256)).size).toBe(2);\n    expect([...result.stored.values()]).toEqual(\n      expect.arrayContaining([firstBytes, secondBytes]),\n    );\n\n    const winner = result.database.prepare(`\n      SELECT mso.object_key\n      FROM comment_submission_items csi\n      JOIN managed_storage_objects mso ON mso.id = csi.storage_object_id\n      WHERE csi.id = \'item-upload\'\n    `).get() as { object_key: string };\n    const winnerUrl = [\n      "https://drive.switch.ch/remote.php/dav/files/test-user",\n      "sample-fabrication-workflow",\n      ...winner.object_key.split("/").map(encodeURIComponent),\n    ].join("/");\n    expect(result.stored.has(winnerUrl)).toBe(true);\n    result.database.close();\n  });\n});\n')

