replace_once('worker/blob-registration-reconciliation.test.ts', '  it("keeps a committed metrology reference asset after its ready-promotion response is lost", async () => {', '\n  it("returns 503 and preserves committed managed bytes when primary reconciliation is unavailable", async () => {\n    const bytes = Uint8Array.from([81, 82, 83, 84, 85]);\n    const sha256 = await sha256Hex(bytesBuffer(bytes));\n    const database = databaseWithUpload("attachment", bytes.byteLength);\n    const stored = new Map<string, Uint8Array>();\n    const deletedUrls: string[] = [];\n    const fetchMock = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {\n      const url = String(input);\n      const method = init?.method || "GET";\n      if (method === "MKCOL") return new Response(null, { status: 201 });\n      if (method === "PUT") {\n        const body = await new Response(init?.body as BodyInit).arrayBuffer();\n        stored.set(url, new Uint8Array(body));\n        return new Response(null, { status: 201 });\n      }\n      if (method === "HEAD") {\n        const value = stored.get(url);\n        return value\n          ? new Response(null, {\n              status: 200,\n              headers: {\n                "content-length": String(value.byteLength),\n                "content-type": "application/octet-stream",\n                etag: \'"managed-authority-test"\',\n              },\n            })\n          : new Response(null, { status: 404 });\n      }\n      if (method === "DELETE") {\n        deletedUrls.push(url);\n        stored.delete(url);\n        return new Response(null, { status: 204 });\n      }\n      throw new Error(`Unexpected SWITCHdrive method ${method}`);\n    });\n    vi.stubGlobal("fetch", fetchMock);\n\n    const env = {\n      AUTH_MODE: "disabled",\n      DB: new FaultD1Database(\n        database,\n        "managed_storage_objects",\n        true,\n      ) as unknown as D1Database,\n      ASSETS: {} as R2Bucket,\n      MANAGED_STORAGE_PROVIDER: "switchdrive",\n      SWITCHDRIVE_WEBDAV_URL:\n        "https://drive.switch.ch/remote.php/dav/files/test-user/",\n      SWITCHDRIVE_USERNAME: "test-user",\n      SWITCHDRIVE_APP_PASSWORD: "test-password",\n    } satisfies Env;\n\n    const response = await worker.fetch(new Request(\n      "https://app.test/api/comment-submissions/submission-upload/items/item-upload/content",\n      {\n        method: "PUT",\n        headers: {\n          "content-type": "application/octet-stream",\n          "x-upload-size": String(bytes.byteLength),\n          "x-content-sha256": sha256,\n        },\n        body: bytes,\n      },\n    ), env, executionContext);\n    expect(response.status).toBe(503);\n    expect(deletedUrls).toEqual([]);\n\n    const row = database.prepare(`\n      SELECT id, object_key, status, sha256\n      FROM managed_storage_objects\n      ORDER BY created_at DESC, id DESC\n      LIMIT 1\n    `).get() as {\n      id: string;\n      object_key: string;\n      status: string;\n      sha256: string;\n    };\n    expect(row.status).toBe("ready");\n    expect(row.sha256).toBe(sha256);\n    const objectUrl = [\n      "https://drive.switch.ch/remote.php/dav/files/test-user",\n      "sample-fabrication-workflow",\n      ...row.object_key.split("/").map(encodeURIComponent),\n    ].join("/");\n    expect(stored.get(objectUrl)).toEqual(bytes);\n    database.close();\n  });\n\n  it("keeps a committed metrology reference asset after its ready-promotion response is lost", async () => {')

replace_between('worker/index.ts', 'app.post("/assets", async (c) => {', '\n\napp.get("/exports/r2/:key{.+}", async (c) => {', 'app.post("/assets", async (c) => {\n  if (!contentLengthWithin(c.req.raw, 10 * 1024 * 1024)) throw new HTTPException(413, { message: "Asset uploads are limited to 10 MB" });\n  const contentType = c.req.header("content-type") || "application/octet-stream";\n  if (!contentType.toLowerCase().startsWith("image/")) throw new HTTPException(415, { message: "Ordinary asset uploads must be images" });\n  const filename = c.req.header("x-filename") || "upload";\n  if (filename.length > 255 || contentType.length > 200) throw new HTTPException(400, { message: "Asset metadata is too long" });\n  const buffer = await c.req.arrayBuffer();\n  if (buffer.byteLength > 10 * 1024 * 1024) throw new HTTPException(413, { message: "Asset uploads are limited to 10 MB" });\n  const sha256 = await digestSha256(buffer);\n  const id = crypto.randomUUID();\n  const key = `${new Date().toISOString().slice(0, 10)}/${id}-${safeObjectName(filename)}`;\n  const registration = await registerR2Asset(c.env, {\n      id,\n      objectKey: key,\n      originalName: filename,\n      mimeType: contentType,\n      byteSize: buffer.byteLength,\n      sha256,\n      actorEmail: c.get("userEmail"),\n      bytes: buffer,\n      findWinner: () => reusableR2Asset(c.env, sha256),\n    }).catch((error: unknown) => {\n      if (error instanceof BlobRegistrationAuthorityUnavailableError) {\n        throw new HTTPException(503, {\n          message: "Asset registration outcome could not be verified. Retry later.",\n        });\n      }\n      throw error;\n    });\n  const payload = {\n    id: registration.asset.id,\n    key: registration.asset.r2_key,\n    deduplicated: registration.deduplicated,\n  };\n  return registration.deduplicated\n    ? c.json(payload)\n    : c.json(payload, 201);\n});')
